# region: gather
def gather(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, factor=10):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: digest
def digest(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return digest(emit(render(gather(raw))))

